CREATE TABLE [purchase].[PurchasePayments]([PurchasePaymentId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_PurchasePayments_Id] DEFAULT NEWSEQUENTIALID(),[PurchaseInvoiceId] UNIQUEIDENTIFIER NOT NULL,[PaymentMethodId] UNIQUEIDENTIFIER NOT NULL,[Amount] DECIMAL(18,2) NOT NULL,[ReferenceNumber] NVARCHAR(100) NULL,[PaymentDate] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_PurchasePayments_Date] DEFAULT SYSUTCDATETIME(),[Status] NVARCHAR(20) NOT NULL CONSTRAINT [DF_PurchasePayments_Status] DEFAULT 'COMPLETED',[CreatedBy] NVARCHAR(256) NULL,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_PurchasePayments_Created] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_PurchasePayments] PRIMARY KEY([PurchasePaymentId]),CONSTRAINT [FK_PurchasePayments_Invoice] FOREIGN KEY([PurchaseInvoiceId]) REFERENCES [purchase].[PurchaseInvoices]([PurchaseInvoiceId]),CONSTRAINT [FK_PurchasePayments_Method] FOREIGN KEY([PaymentMethodId]) REFERENCES [sales].[PaymentMethods]([PaymentMethodId]),CONSTRAINT [CK_PurchasePayments_Amount] CHECK([Amount]>0));
GO
CREATE INDEX [IX_PurchasePayments_Invoice] ON [purchase].[PurchasePayments]([PurchaseInvoiceId],[PaymentDate]);
